use std::net::{IpAddr, Ipv4Addr, SocketAddr};
use std::time::Duration;
use actix_web::{web, App, HttpServer, HttpRequest, HttpResponse, middleware};
use serde::{Deserialize, Serialize};
use serde_json::json;
use reqwest::Client;
use trust_dns_resolver::config::*;
use trust_dns_resolver::TokioAsyncResolver;

#[derive(Deserialize)]
struct WebhookConfig {
    callback_url: String,
    event_type: String,
    secret: String,
}

#[derive(Serialize)]
struct WebhookResponse {
    status: String,
    delivered: bool,
}

const KUBERNETES_SERVICE_CIDR: &str = "10.96.0.0/12";
const POD_NETWORK_CIDR: &str = "10.244.0.0/16";
const NODE_LOCAL_CIDR: &str = "192.168.0.0/16";
const LINK_LOCAL_CIDR: &str = "169.254.0.0/16";
const METADATA_IP: &str = "169.254.169.254";

fn is_ip_in_cidr(ip: &Ipv4Addr, cidr: &str) -> bool {
    let parts: Vec<&str> = cidr.split('/').collect();
    if parts.len() != 2 { return false; }
    let network: Ipv4Addr = parts[0].parse().unwrap_or(Ipv4Addr::new(0,0,0,0));
    let prefix_len: u32 = parts[1].parse().unwrap_or(32);
    let mask = if prefix_len == 0 { 0u32 } else { !0u32 << (32 - prefix_len) };
    let ip_bits = u32::from(*ip);
    let net_bits = u32::from(network);
    (ip_bits & mask) == (net_bits & mask)
}

fn is_internal_ip(ip: &IpAddr) -> bool {
    match ip {
        IpAddr::V4(v4) => {
            if v4.is_loopback() || v4.is_broadcast() || v4.is_unspecified() {
                return true;
            }
            if is_ip_in_cidr(v4, "10.0.0.0/8") { return true; }
            if is_ip_in_cidr(v4, "172.16.0.0/12") { return true; }
            if is_ip_in_cidr(v4, NODE_LOCAL_CIDR) { return true; }
            if is_ip_in_cidr(v4, LINK_LOCAL_CIDR) { return true; }
            if is_ip_in_cidr(v4, KUBERNETES_SERVICE_CIDR) { return true; }
            if is_ip_in_cidr(v4, POD_NETWORK_CIDR) { return true; }
            false
        }
        IpAddr::V6(v6) => {
            v6.is_loopback() || v6.is_unspecified()
        }
    }
}

async fn resolve_and_validate(hostname: &str) -> Result<IpAddr, String> {
    let resolver = TokioAsyncResolver::tokio(
        ResolverConfig::default(),
        ResolverOpts::default(),
    ).map_err(|e| format!("Resolver init failed: {}", e))?;

    let response = resolver.lookup_ip(hostname)
        .await
        .map_err(|e| format!("DNS resolution failed: {}", e))?;

    let ip = response.iter().next()
        .ok_or_else(|| "No IP addresses found".to_string())?;

    if is_internal_ip(&ip) {
        return Err(format!("Blocked internal IP: {}", ip));
    }

    Ok(ip)
}

async fn deliver_webhook(
    config: web::Json<WebhookConfig>,
) -> HttpResponse {
    let url = match url::Url::parse(&config.callback_url) {
        Ok(u) => u,
        Err(_) => return HttpResponse::BadRequest().json(WebhookResponse {
            status: "invalid_url".into(),
            delivered: false,
        }),
    };

    let hostname = match url.host_str() {
        Some(h) => h.to_string(),
        None => return HttpResponse::BadRequest().json(WebhookResponse {
            status: "no_host".into(),
            delivered: false,
        }),
    };

    // Resolve and validate the target is not internal
    let validated_ip = match resolve_and_validate(&hostname).await {
        Ok(ip) => ip,
        Err(e) => return HttpResponse::Forbidden().json(WebhookResponse {
            status: e,
            delivered: false,
        }),
    };

    // Pin the connection to the validated IP to prevent DNS rebinding
    let port = url.port_or_known_default().unwrap_or(443);
    let pinned_addr = SocketAddr::new(validated_ip, port);
    let pinned_url = format!("{}://{}:{}{}",
        url.scheme(),
        validated_ip,
        port,
        url.path()
    );

    // Build the HTTP client with a reasonable timeout
    let client = Client::builder()
        .timeout(Duration::from_secs(10))
        .redirect(reqwest::redirect::Policy::none())
        .resolve(&hostname, pinned_addr)
        .build()
        .unwrap();

    // Deliver the webhook using the original URL but pinned to validated IP
    // The .resolve() ensures the connection goes to our validated address
    let payload = json!({ "event": config.event_type });
    let result = client
        .post(&config.callback_url)
        .header("X-Webhook-Secret", &config.secret)
        .header("X-Event-Type", &config.event_type)
        .header("X-Validated-IP", validated_ip.to_string())
        .json(&payload)
        .send()
        .await;

    // Second validation: verify the connection went to expected IP
    match result {
        Ok(resp) => {
            if let Some(remote) = resp.remote_addr() {
                if is_internal_ip(&remote.ip()) {
                    return HttpResponse::Forbidden().json(WebhookResponse {
                        status: "connection_to_internal_blocked".into(),
                        delivered: false,
                    });
                }
            }
            HttpResponse::Ok().json(WebhookResponse {
                status: format!("delivered_status_{}", resp.status().as_u16()),
                delivered: true,
            })
        },
        Err(e) => HttpResponse::BadGateway().json(WebhookResponse {
            status: format!("delivery_failed: {}", e),
            delivered: false,
        }),
    }
}

async fn health_check() -> HttpResponse {
    HttpResponse::Ok().body("ok")
}

#[actix_web::main]
async fn main() -> std::io::Result<()> {
    env_logger::init();
    HttpServer::new(|| {
        App::new()
            .route("/webhooks/deliver", web::post().to(deliver_webhook))
            .route("/health", web::get().to(health_check))
    })
    .bind("0.0.0.0:8080")?
    .run()
    .await
}
